"""AES-GCM solver using cryptography's allocation-saving API."""
from cryptography.hazmat.primitives.ciphers.aead import AESGCM


class Solver:
    def solve(self, problem, **kwargs):
        plaintext = problem["plaintext"]
        result = bytearray(len(plaintext) + 16)
        AESGCM(problem["key"]).encrypt_into(
            problem["nonce"],
            plaintext,
            problem["associated_data"],
            result,
        )
        # is_solution specifically requires bytes rather than buffer views.
        return {
            "ciphertext": bytes(result[:-16]),
            "tag": bytes(result[-16:]),
        }
